# Deployed from: hemsoft-dev/set-it-free-loop/deployment/infrastructure/sfl-pr-review-auto.yml@89425320ace3127a829d86e3b642fe2b31fd979e
# To upgrade: re-run deploy-workflow.ps1 at the desired SHA
# Deployed from HemSoft/set-it-free-loop. The deployment command replaces this
# source pin with the immutable source SHA.
# Source: hemsoft-dev/set-it-free-loop/deployment/infrastructure/sfl-pr-review-auto.yml@89425320ace3127a829d86e3b642fe2b31fd979e
name: SFL Codex Review Observer
run-name: >-
  ${{ github.event_name == 'issue_comment' &&
      startsWith(github.event.comment.body, '@codex review') &&
      format('SFL Codex review request #{0}', github.event.issue.number) ||
      format('SFL {0} event', github.event_name) }}

on:
  push:
    branches: ['main']
  issue_comment:
    types: [created]
  pull_request_review:
    types: [submitted]
  pull_request_target:
    types: [opened, reopened, edited, synchronize]

permissions: {}

env:
  SFL_REVIEW_BASE_BRANCH: 'main'

jobs:
  invalidate-review-request:
    name: Invalidate prior gate for registered review request
    if: >-
      vars.SFL_ENABLED != 'false' &&
      github.event_name == 'issue_comment' &&
      github.event.issue.pull_request &&
      startsWith(github.event.comment.body, '@codex review')
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      checks: write
      contents: read
      issues: read
      pull-requests: read
      statuses: write
    steps:
      - name: Fail the gate while a registered Codex review is pending
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ github.token }}
          script: |
            const {owner, repo} = context.repo;
            // BEGIN TESTABLE REQUESTER AUTHORIZATION
            const requesterAllowed = async login => {
              if (owner.toLowerCase() !== "hemsoft-dev") {
                return (login || "").toLowerCase() === owner.toLowerCase();
              }
              if (!/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(login || "")) return false;
              let permission;
              try {
                const response = await github.rest.repos.getCollaboratorPermissionLevel({
                  owner, repo, username: login,
                });
                permission = response.data;
              } catch (error) {
                if (error.status === 404 || error.status === 403) return false;
                throw error;
              }
              if (!permission.user ||
                  (permission.user.login || "").toLowerCase() !== login.toLowerCase()) {
                throw new Error("Review requester permission identity mismatch");
              }
              return ["admin", "maintain", "write"].includes(permission.permission);
            };
            // END TESTABLE REQUESTER AUTHORIZATION
            const pullNumber = context.payload.issue.number;
            const commentId = context.payload.comment.id;
            const comment = await github.rest.issues.getComment({
              owner, repo, comment_id: commentId,
            });
            if (!await requesterAllowed(comment.data.user && comment.data.user.login)) {
              core.info("Review requester does not have write or higher repository permission");
              return;
            }
            if (comment.data.updated_at !== comment.data.created_at) {
              core.info("Edited Codex review requests are not accepted");
              return;
            }
            const pull = await github.rest.pulls.get({
              owner, repo, pull_number: pullNumber,
            });
            const defaultBranch = context.payload.repository.default_branch;
            const headRepo = pull.data.head.repo && pull.data.head.repo.full_name;
            if (pull.data.state !== "open" ||
                pull.data.base.ref !== defaultBranch ||
                !headRepo ||
                headRepo.toLowerCase() !== `${owner}/${repo}`.toLowerCase()) {
              core.info("Codex review request does not target a supported open pull request");
              return;
            }
            const currentHead = pull.data.head.sha;
            const currentBase = pull.data.base.sha;
            const reviewerChecks = async () => github.paginate(
              github.rest.checks.listForRef,
              {
                owner,
                repo,
                ref: currentHead,
                check_name: "SFL Reviewer Gate Runner",
                filter: "all",
                per_page: 100,
              },
              response => response.data,
            );
            const reviewContextToken = checks => {
              const invalidation = checks.filter(
                check => check.app && check.app.id === 15368 &&
                  ((check.external_id || "").startsWith("sfl-codex-review:pull-context:") ||
                   (check.external_id || "").startsWith("sfl-codex-review:base-advance:")),
              ).sort((left, right) => right.id - left.id)[0];
              return invalidation ? invalidation.external_id : "none";
            };
            const contextToken = reviewContextToken(await reviewerChecks());
            const marker = `<!-- sfl-codex-review:head=${currentHead.toLowerCase()};base=${currentBase.toLowerCase()};context=${contextToken} -->`;
            if ((comment.data.body || "").trim() !== `@codex review\n\n${marker}`) {
              core.info("Codex review request does not contain the exact current SFL marker");
              return;
            }
            const targetURL = (comment.data.html_url || "").toLowerCase();
            let registered = false;
            for (let attempt = 0; attempt < 12 && !registered; attempt += 1) {
              const statuses = await github.paginate(
                github.rest.repos.listCommitStatusesForRef,
                {owner, repo, ref: currentHead, per_page: 100},
              );
              const author = ((comment.data.user && comment.data.user.login) || "").toLowerCase();
              for (const status of statuses) {
                const creator = ((status.creator && status.creator.login) || "").toLowerCase();
                if (status.context === "SFL Codex Review Request Registry" &&
                    creator === author && (status.target_url || "").toLowerCase() === targetURL &&
                    await requesterAllowed(creator)) {
                  registered = true;
                  break;
                }
              }
              if (!registered && attempt < 11) {
                await new Promise(resolve => setTimeout(resolve, 5000));
              }
            }
            if (!registered) {
              core.info("Codex review request was not registered by gh sfl review");
              return;
            }
            const confirmedPull = await github.rest.pulls.get({
              owner, repo, pull_number: pullNumber,
            });
            const confirmedChecks = await reviewerChecks();
            if (confirmedPull.data.state !== "open" ||
                confirmedPull.data.head.sha !== currentHead ||
                confirmedPull.data.base.sha !== currentBase ||
                reviewContextToken(confirmedChecks) !== contextToken) {
              core.info("Pull request context changed before the review request could invalidate the gate");
              return;
            }
            const terminalRequestIdentity = `:request:${commentId}:at:`;
            if (confirmedChecks.some(
              check => check.app && check.app.id === 15368 &&
                check.status === "completed" &&
                (check.external_id || "").includes(terminalRequestIdentity),
            )) {
              core.info("This registered Codex review request already has a terminal SFL gate");
              return;
            }
            const externalId = `sfl-codex-review:request-pending:${commentId}`;
            if (confirmedChecks.some(
              check => check.app && check.app.id === 15368 && check.external_id === externalId,
            )) {
              core.info("This registered Codex review request already invalidated the prior gate");
              return;
            }
            const reason = `Registered Codex review request ${commentId} is pending for pull request #${pullNumber}`;
            await github.rest.checks.create({
              owner,
              repo,
              name: "SFL Reviewer Gate Runner",
              head_sha: currentHead,
              status: "completed",
              conclusion: "failure",
              completed_at: new Date().toISOString(),
              details_url: comment.data.html_url,
              external_id: externalId,
              output: {title: "SFL Codex review pending", summary: reason},
            });
            await github.rest.repos.createCommitStatus({
              owner,
              repo,
              sha: currentHead,
              state: "pending",
              context: "SFL Reviewer Gate Runner",
              target_url: comment.data.html_url,
              description: "Waiting for the registered Codex review result",
            });
            core.setFailed(reason);


  observe:
    name: Observe authenticated Codex review
    if: >-
      vars.SFL_ENABLED != 'false' &&
      github.event.sender.id == 199175422 &&
      ((github.event_name == 'issue_comment' && github.event.issue.pull_request) ||
      github.event_name == 'pull_request_review')
    concurrency:
      group: sfl-codex-review-serialize-${{ github.repository }}-${{ github.event.issue.number || github.event.pull_request.number }}
      cancel-in-progress: false
      queue: max
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      actions: read
      checks: write
      contents: read
      issues: read
      pull-requests: read
      statuses: write
    steps:
      - name: Validate Codex result and publish immutable-head gate
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ github.token }}
          script: |
            // BEGIN TESTABLE CODEX OBSERVER
            function classifyCodexArtifact(input) {
              const botId = 199175422;
              const botLogin = "chatgpt-codex-connector[bot]";
              const appId = 1144995;
              const appSlug = "chatgpt-codex-connector";
              const appOwner = "openai";
              const artifact = input.artifact || {};
              const user = artifact.user || {};
              const app = artifact.performed_via_github_app;
              const body = artifact.body || "";

              if (user.id !== botId || user.login !== botLogin) {
                return { action: "ignore", reason: "artifact author is not the Codex connector bot" };
              }

              if (input.eventName === "issue_comment") {
                if (!app || app.id !== appId || app.slug !== appSlug ||
                    !app.owner || app.owner.login !== appOwner) {
                  return { action: "ignore", reason: "comment lacks the expected Codex GitHub App provenance" };
                }
              } else if (input.eventName === "pull_request_review") {
                // GitHub's review REST object currently omits performed_via_github_app.
                // If GitHub begins returning it, require the same immutable App identity.
                if (app && (app.id !== appId || app.slug !== appSlug ||
                    !app.owner || app.owner.login !== appOwner)) {
                  return { action: "ignore", reason: "review has conflicting GitHub App provenance" };
                }
                if (artifact.state !== "COMMENTED") {
                  return { action: "failure", reason: "Codex review has an unexpected state" };
                }
              } else {
                return { action: "ignore", reason: "unsupported event" };
              }

              const currentHead = (input.currentHead || "").toLowerCase();
              const resolvedSha = (input.resolvedSha || "").toLowerCase();
              const reviewCommit = (input.reviewCommit || "").toLowerCase();
              if (reviewCommit && reviewCommit !== currentHead) {
                return { action: "ignore", reason: "Codex artifact is stale for the current pull request head" };
              }
              if (!resolvedSha) {
                if (input.eventName === "issue_comment") {
                  return { action: "ignore", reason: "Codex comment cannot be bound to a reviewed commit" };
                }
                return { action: "failure", reason: "Codex artifact has a malformed or unresolvable reviewed commit" };
              }
              if (resolvedSha !== currentHead) {
                return { action: "ignore", reason: "Codex artifact is stale for the current pull request head" };
              }
              if (!input.requestMatchesCurrentBase) {
                return { action: "ignore", reason: "Codex artifact is not bound to a review request for the current head and base" };
              }
              if (input.openPullCount !== 1) {
                return { action: "failure", reason: "The current head is shared by multiple open pull requests; use a separate branch before requesting review" };
              }

              if (input.eventName === "issue_comment" &&
                  /^Codex Review: Didn't find any major issues\./.test(body)) {
                return { action: "success", reason: "Codex found no major issues on the current head" };
              }
              if (input.eventName === "pull_request_review" &&
                  (input.inlineCount > 0 || /automated review suggestions/i.test(body))) {
                return { action: "failure", reason: "Codex reported review findings on the current head" };
              }
              return { action: "failure", reason: "authenticated Codex artifact has an unknown result shape" };
            }

            function isActiveInvalidationRun(run, pullNumber, owner) {
              if (!run || run.status === "completed") return false;
              if (run.event === "push") return true;
              if (run.event === "issue_comment") {
                // Identify a request invalidation candidate for this PR;
                // activeInvalidationRuns verifies the actor before waiting.
                return Boolean(run.actor && run.actor.login) &&
                  run.display_title === `SFL Codex review request #${pullNumber}`;
              }
              return run.event === "pull_request_target" &&
                (run.pull_requests || []).some(candidate => candidate.number === pullNumber);
            }

            function requestGateExternalIdPrefix(pullNumber, currentBase, contextToken, requestId, requestTime) {
              return `sfl-codex-review:pull:${pullNumber}:base:${currentBase.toLowerCase()}:context:${encodeURIComponent(contextToken)}:request:${requestId}:at:${requestTime}`;
            }

            function requestGateExternalId(pullNumber, currentBase, contextToken, requestId, requestTime, artifactIdentity) {
              return `${requestGateExternalIdPrefix(pullNumber, currentBase, contextToken, requestId, requestTime)}:artifact:${artifactIdentity}`;
            }
            // END TESTABLE CODEX OBSERVER

            const {owner, repo} = context.repo;
            // BEGIN TESTABLE REQUESTER AUTHORIZATION
            const requesterAllowed = async login => {
              if (owner.toLowerCase() !== "hemsoft-dev") {
                return (login || "").toLowerCase() === owner.toLowerCase();
              }
              if (!/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(login || "")) return false;
              let permission;
              try {
                const response = await github.rest.repos.getCollaboratorPermissionLevel({
                  owner, repo, username: login,
                });
                permission = response.data;
              } catch (error) {
                if (error.status === 404 || error.status === 403) return false;
                throw error;
              }
              if (!permission.user ||
                  (permission.user.login || "").toLowerCase() !== login.toLowerCase()) {
                throw new Error("Review requester permission identity mismatch");
              }
              return ["admin", "maintain", "write"].includes(permission.permission);
            };
            // END TESTABLE REQUESTER AUTHORIZATION
            const eventName = context.eventName;
            const pullNumber = eventName === "issue_comment"
              ? context.payload.issue.number
              : context.payload.pull_request.number;
            const artifactId = eventName === "issue_comment"
              ? context.payload.comment.id
              : context.payload.review.id;
            let artifact;
            let inlineCount = 0;
            let reviewCommit = "";
            if (eventName === "issue_comment") {
              const response = await github.rest.issues.getComment({
                owner, repo, comment_id: artifactId,
              });
              artifact = response.data;
            } else {
              const response = await github.rest.pulls.getReview({
                owner, repo, pull_number: pullNumber, review_id: artifactId,
              });
              artifact = response.data;
              reviewCommit = artifact.commit_id || "";
              const comments = await github.paginate(
                "GET /repos/{owner}/{repo}/pulls/{pull_number}/reviews/{review_id}/comments",
                {owner, repo, pull_number: pullNumber, review_id: artifactId, per_page: 100},
              );
              inlineCount = comments.length;
            }

            const pull = await github.rest.pulls.get({
              owner, repo, pull_number: pullNumber,
            });
            if (pull.data.state !== "open") {
              core.info("The pull request is no longer open; no SFL gate was published");
              return;
            }
            const defaultBranch = context.payload.repository && context.payload.repository.default_branch;
            if (!defaultBranch) throw new Error("Could not determine the repository default branch");
            if (pull.data.base.ref !== defaultBranch) {
              core.info(`Pull requests targeting ${pull.data.base.ref} are unsupported; SFL reviews require the default branch ${defaultBranch}`);
              return;
            }
            const headRepo = pull.data.head.repo && pull.data.head.repo.full_name;
            if (!headRepo || headRepo.toLowerCase() !== `${owner}/${repo}`.toLowerCase()) {
              core.info("Fork pull requests are unsupported; no SFL gate was published");
              return;
            }
            const currentBase = pull.data.base.sha;
            const currentHead = pull.data.head.sha;
            // BEGIN TESTABLE REQUIRED GATE TARGET
            function requiredGateTarget(pull) {
              return pull.head.sha.toLowerCase();
            }
            // END TESTABLE REQUIRED GATE TARGET
            const configuredBaseBranch = process.env.SFL_REVIEW_BASE_BRANCH || "";
            if (!configuredBaseBranch) throw new Error("The deployed SFL review base branch is empty");
            if (defaultBranch !== configuredBaseBranch) {
              const reason = `Repository default branch ${defaultBranch} differs from deployed SFL review base ${configuredBaseBranch}; redeploy SFL before accepting review results`;
              await github.rest.checks.create({
                owner,
                repo,
                name: "SFL Reviewer Gate Runner",
                head_sha: currentHead,
                status: "completed",
                conclusion: "failure",
                completed_at: new Date().toISOString(),
                details_url: artifact.html_url || pull.data.html_url,
                external_id: `sfl-codex-review:default-branch-mismatch:${encodeURIComponent(configuredBaseBranch)}:${encodeURIComponent(defaultBranch)}`,
                output: {title: "SFL Codex review blocked", summary: reason},
              });
              await github.rest.repos.createCommitStatus({
                owner,
                repo,
                sha: currentHead,
                state: "failure",
                context: "SFL Reviewer Gate Runner",
                target_url: artifact.html_url || pull.data.html_url,
                description: "The configured review base no longer matches the default branch",
              });
              core.setFailed(reason);
              return;
            }
            const match = (artifact.body || "").match(
              /\*\*Reviewed commit:\*\*\s+`([0-9a-f]{7,40})`/i,
            );
            let resolvedSha = "";
            if (match) {
              try {
                const commit = await github.rest.repos.getCommit({
                  owner, repo, ref: match[1],
                });
                resolvedSha = commit.data.sha;
              } catch (error) {
                if (error.status !== 404 && error.status !== 422) throw error;
              }
            }
            const artifactBindsCurrentHead = eventName === "issue_comment"
              ? Boolean(match) && resolvedSha.toLowerCase() === currentHead.toLowerCase()
              : reviewCommit.toLowerCase() === currentHead.toLowerCase() &&
                (!match || resolvedSha.toLowerCase() === currentHead.toLowerCase());
            const artifactIdentity = `${eventName === "issue_comment" ? "c" : "r"}${artifactId}`;
            const artifactSuffix = `:artifact:${artifactIdentity}`;
            const artifactChecks = await github.paginate(
              github.rest.checks.listForRef,
              {
                owner,
                repo,
                ref: currentHead,
                check_name: "SFL Reviewer Gate Runner",
                filter: "all",
                per_page: 100,
              },
              response => response.data,
            );
            const artifactAlreadyConsumed = artifactChecks.some(
              check => check.app && check.app.id === 15368 &&
                (check.external_id || "").endsWith(artifactSuffix),
            );
            if (artifactAlreadyConsumed) {
              core.info("This exact Codex artifact already completed a review request; verifying its required status");
            }
            const artifactTime = Date.parse(artifact.created_at || artifact.submitted_at || "");
            let requesterPermissions = new Map();
            // BEGIN TESTABLE REQUESTER REFRESH
            const refreshRequesterPermissions = async (comments, statuses) => {
              const registrations = statuses.filter(status =>
                status.context === "SFL Codex Review Request Registry" &&
                (status.target_url || "").toLowerCase().startsWith(requestTargetPrefix));
              const registeredIds = new Set(registrations.map(status =>
                Number(status.target_url.toLowerCase().slice(requestTargetPrefix.length))));
              const candidates = comments.filter(comment =>
                registeredIds.has(comment.id) ||
                ((comment.body || "").startsWith("@codex review") &&
                 (comment.body || "").includes(headMarker)));
              const matchingCreators = registrations.filter(status => {
                const id = Number(status.target_url.toLowerCase().slice(requestTargetPrefix.length));
                const comment = candidates.find(candidate => candidate.id === id);
                return comment && ((comment.user && comment.user.login) || "").toLowerCase() ===
                  ((status.creator && status.creator.login) || "").toLowerCase();
              });
              const logins = new Set([
                ...candidates.map(comment => (comment.user && comment.user.login) || ""),
                ...matchingCreators.map(status => (status.creator && status.creator.login) || ""),
              ]);
              const refreshed = new Map();
              for (const login of logins) {
                refreshed.set(login.toLowerCase(), await requesterAllowed(login));
              }
              requesterPermissions = refreshed;
            };
            // END TESTABLE REQUESTER REFRESH
            const isOwnerRequest = comment => Boolean(comment) &&
              requesterPermissions.get(((comment.user && comment.user.login) || "").toLowerCase()) === true;
            const headMarker = `<!-- sfl-codex-review:head=${currentHead.toLowerCase()};base=`;
            const baseMarker = `${headMarker}${currentBase.toLowerCase()};`;
            const requestTargetPrefix = `https://github.com/${owner}/${repo}/pull/${pullNumber}#issuecomment-`.toLowerCase();
            // BEGIN TESTABLE REQUEST REGISTRATION
            const historicalRequestIdsFromStatuses = (statuses, comments = triggerComments) => new Set(statuses.flatMap(status => {
              if (status.context !== "SFL Codex Review Request Registry") {
                return [];
              }
              const targetURL = (status.target_url || "").toLowerCase();
              if (!targetURL.startsWith(requestTargetPrefix)) return [];
              const requestId = Number(targetURL.slice(requestTargetPrefix.length));
              const comment = comments.find(candidate => candidate.id === requestId);
              const author = ((comment && comment.user && comment.user.login) || "").toLowerCase();
              const creator = ((status.creator && status.creator.login) || "").toLowerCase();
              return Number.isSafeInteger(requestId) && requestId > 0 &&
                String(requestId) === targetURL.slice(requestTargetPrefix.length) &&
                Boolean(creator) && (!comment || author === creator) &&
                (owner.toLowerCase() === "hemsoft-dev" || creator === owner.toLowerCase()) ? [requestId] : [];
            }));
            const registeredRequestIdsFromStatuses = (statuses, comments = triggerComments) =>
              new Set([...historicalRequestIdsFromStatuses(statuses, comments)].filter(id =>
                isOwnerRequest(comments.find(comment => comment.id === id))));
            const hasHistoricalBaseConflict = (comments, statuses) => {
              const historical = historicalRequestIdsFromStatuses(statuses, comments);
              for (const id of historical) {
                const comment = comments.find(candidate => candidate.id === id);
                if (!comment) return true;
                const creator = ((comment.user && comment.user.login) || "").toLowerCase();
                const registration = statuses.filter(status =>
                  status.context === "SFL Codex Review Request Registry" &&
                  (status.target_url || "").toLowerCase() === `${requestTargetPrefix}${id}` &&
                  ((status.creator && status.creator.login) || "").toLowerCase() === creator).at(-1);
                const prefix = `SFL Codex request comment ${id} for PR #${pullNumber} base `;
                const description = (registration && registration.description) || "";
                const originalBase = description.startsWith(prefix) ? description.slice(prefix.length) : "";
                if (/^[0-9a-f]{40}$/.test(originalBase)) {
                  if (originalBase !== currentBase.toLowerCase()) return true;
                } else if (comment.updated_at !== comment.created_at ||
                           !(comment.body || "").includes(baseMarker)) {
                  // Old registries lack an immutable base. Edits erase that evidence.
                  return true;
                }
              }
              return false;
            };
            // END TESTABLE REQUEST REGISTRATION
            let triggerComments = [];
            let requestStatuses = [];
            let latestPotentialRequest;
            let latestPotentialRequestRegistered = false;
            for (let attempt = 0; attempt < 12; attempt += 1) {
              [triggerComments, requestStatuses] = await Promise.all([
                github.paginate(github.rest.issues.listComments, {
                  owner, repo, issue_number: pullNumber, per_page: 100,
                }),
                github.paginate(
                  github.rest.repos.listCommitStatusesForRef,
                  {owner, repo, ref: currentHead, per_page: 100},
                ),
              ]);
              await refreshRequesterPermissions(triggerComments, requestStatuses);
              const potentialRequests = triggerComments.map(comment => ({
                comment,
                requestTime: Date.parse(comment.created_at || ""),
                updatedTime: Date.parse(comment.updated_at || ""),
              })).filter(({comment, requestTime, updatedTime}) => {
                const contextMatch = /;context=(.*?) -->/.exec(comment.body || "");
                return isOwnerRequest(comment) && contextMatch && contextMatch[1] &&
                  (comment.body || "") === `@codex review\n\n${baseMarker}context=${contextMatch[1]} -->` &&
                  Number.isFinite(requestTime) && requestTime <= artifactTime &&
                  Number.isFinite(updatedTime) && updatedTime === requestTime;
              }).sort((left, right) =>
                left.requestTime - right.requestTime || left.comment.id - right.comment.id);
              latestPotentialRequest = potentialRequests[potentialRequests.length - 1];
              const visibleRegistrations = registeredRequestIdsFromStatuses(requestStatuses);
              latestPotentialRequestRegistered = Boolean(latestPotentialRequest) &&
                visibleRegistrations.has(latestPotentialRequest.comment.id);
              if (latestPotentialRequestRegistered) break;
              if (attempt < 11) await new Promise(resolve => setTimeout(resolve, 5000));
            }
            if (!latestPotentialRequestRegistered) {
              core.info("No registered Codex review request materialized for this artifact");
              return;
            }
            const registeredRequestIds = historicalRequestIdsFromStatuses(requestStatuses);
            // BEGIN TESTABLE REQUEST ELIGIBILITY
            const requestContextFromBody = body => {
              const contextMatch = /;context=(.*?) -->/.exec(body || "");
              return contextMatch && contextMatch[1] ? contextMatch[1] : "";
            };
            const requestOrder = (left, right) =>
              left.requestTime - right.requestTime || left.comment.id - right.comment.id;
            const requestCandidates = (comments, beforeTime, registrations = registeredRequestIds) => comments.map(
              comment => ({
                comment,
                requestTime: Date.parse(comment.created_at || ""),
                updatedTime: Date.parse(comment.updated_at || ""),
              }),
            ).filter(
              ({comment, requestTime, updatedTime}) =>
                registrations.has(comment.id) &&
                (comment.body || "").includes(baseMarker) &&
                (comment.body || "") === `@codex review\n\n${baseMarker}context=${requestContextFromBody(comment.body)} -->` &&
                Number.isFinite(requestTime) && requestTime <= beforeTime &&
                Number.isFinite(updatedTime) && updatedTime === requestTime,
            ).sort(requestOrder);
            const hasTerminalGateBefore = (request, contextToken, nextRequestTime, checkRuns) => {
              const prefix = requestGateExternalIdPrefix(
                pullNumber,
                currentBase,
                contextToken,
                request.comment.id,
                request.requestTime,
              );
              return checkRuns.some(check => {
                const completedTime = Date.parse(check.completed_at || "");
                return check.app && check.app.id === 15368 &&
                  check.status === "completed" &&
                  (check.external_id === prefix ||
                   (check.external_id || "").startsWith(`${prefix}:artifact:`)) &&
                  Number.isFinite(completedTime) && completedTime < nextRequestTime;
              });
            };
            const eligibleReviewRequests = (
              comments, checkRuns, beforeTime, registrations = registeredRequestIds,
            ) => {
              const previousByContext = new Map();
              const eligible = [];
              for (const candidate of requestCandidates(comments, beforeTime, registrations)) {
                const requestContext = requestContextFromBody(candidate.comment.body);
                if (!requestContext) continue;
                const previous = previousByContext.get(requestContext);
                if (!previous ||
                    hasTerminalGateBefore(previous, requestContext, candidate.requestTime, checkRuns)) {
                  eligible.push({...candidate, contextToken: requestContext});
                  previousByContext.set(requestContext, candidate);
