            requiredPublished = await github.rest.repos.createCommitStatus({
              owner,
              repo,
              sha: requiredGateSha,
              state: "pending",
              context: "SFL Reviewer Gate Runner",
              target_url: detailsURL,
              description: "Validating Codex review for the immutable pull request head",
            });
            await github.rest.checks.update({
              owner,
              repo,
              check_run_id: published.data.id,
              status: "completed",
              conclusion: "success",
              completed_at: new Date().toISOString(),
              details_url: detailsURL,
              external_id: externalId,
              output: {title, summary: result.reason + "\n\n<!-- sfl-gate-execution:" + Buffer.from(JSON.stringify({
                repository_id: context.payload.repository.id,
                repository: `${owner}/${repo}`,
                run_id: context.runId,
                run_attempt: Number(process.env.GITHUB_RUN_ATTEMPT),
                execution_sha: context.sha,
                workflow_sha: process.env.GITHUB_WORKFLOW_SHA,
                workflow_path: ".github/workflows/sfl-pr-review-auto.yml",
                event: context.eventName,
