            const supersedingContext = reviewerChecks.find(
              check => check.app && check.app.id === 15368 &&
                supersedesInvalidation(check.external_id, contextChangeTime, context.runId),
            );
            if (supersedingContext) {
              core.info(`Pull request #${pull.number} has a newer invalidation context; skipping stale invalidation`);
              return;
            }
            const newerSuccess = reviewerChecks.some(
              check => check.app && check.app.id === 15368 &&
                check.conclusion === "success" &&
                check.external_id && check.external_id.startsWith(
                  `sfl-codex-review:pull:${pull.number}:base:${pull.base.sha.toLowerCase()}:`,
                ) &&
                check.external_id.includes(`:context:${encodeURIComponent(invalidationId)}:`),
            );
            if (newerSuccess) {
              core.info(`Pull request #${pull.number} already has a successful Codex gate completed after this context change`);
              return;
            }
            const livePull = await github.rest.pulls.get({
              owner, repo, pull_number: pull.number,
            });
            if (livePull.data.state !== "open" ||
                livePull.data.head.sha !== pull.head.sha ||
                livePull.data.base.sha !== pull.base.sha) {
              core.info(`Pull request #${pull.number} changed again after this context event; skipping stale invalidation`);
              return;
            }
            const reason = context.payload.action === "edited"
              ? `Pull request base changed to ${pull.base.ref} at ${pull.base.sha}; advance the branch to a new head, then request a Codex review.`
              : context.payload.action === "synchronize"
                ? `Pull request head changed to ${pull.head.sha}; request a Codex review for this exact head and base.`
                : context.payload.action === "reopened"
                  ? `Pull request #${pull.number} reopened; advance the branch to a new head before requesting review because earlier native artifacts cannot prove their base.`
                  : `Pull request #${pull.number} opened for ${pull.base.ref} at ${pull.base.sha}; request a Codex review for this exact pull request context.`;
            const finalChecks = await github.paginate(
              github.rest.checks.listForRef,
              {
                owner,
                repo,
                ref: pull.head.sha,
                check_name: "SFL Reviewer Gate Runner",
                filter: "all",
                per_page: 100,
              },
              response => response.data,
            );
            const finalContextExists = finalChecks.some(
              check => check.app && check.app.id === 15368 &&
                (check.external_id === invalidationId ||
                 supersedesInvalidation(check.external_id, contextChangeTime, context.runId)),
            );
            const finalSuccess = finalChecks.some(
              check => check.app && check.app.id === 15368 &&
                check.conclusion === "success" &&
                check.external_id && check.external_id.startsWith(
                  `sfl-codex-review:pull:${pull.number}:base:${pull.base.sha.toLowerCase()}:`,
                ) &&
                check.external_id.includes(`:context:${encodeURIComponent(invalidationId)}:`),
            );
            if (finalContextExists || finalSuccess) {
              core.info(`Pull request #${pull.number} received a newer context or successful Codex gate while invalidation was running`);
              return;
            }
            await github.rest.checks.create({
              owner,
              repo,
              name: "SFL Reviewer Gate Runner",
              head_sha: pull.head.sha,
              status: "completed",
              conclusion: "failure",
              completed_at: new Date().toISOString(),
              details_url: pull.html_url,
              external_id: invalidationId,
              output: {
                title: "SFL Codex review invalidated",
                summary: reason,
                text: JSON.stringify({schema: 1, pull_number: pull.number,
                  action: context.payload.action, base_sha: pull.base.sha.toLowerCase()}),
              },
            });
            await github.rest.repos.createCommitStatus({
              owner,
              repo,
              sha: pull.head.sha,
              state: "failure",
              context: "SFL Reviewer Gate Runner",
              target_url: pull.html_url,
              description: "The pull request context changed after review",
            });
            core.info(reason);

  invalidate-base-advance:
    name: Invalidate Codex reviews after base advance
    if: github.event_name == 'push'
    runs-on: ubuntu-latest
    timeout-minutes: 30
    concurrency:
      group: sfl-codex-review-base-advance-${{ github.repository }}-${{ github.ref }}
      cancel-in-progress: true
    permissions:
      actions: read
      checks: write
      contents: read
      pull-requests: read
      statuses: write
    steps:
      - name: Fail gates for pull requests whose base branch advanced
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ github.token }}
          script: |
            // BEGIN TESTABLE INVALIDATION ORDER
            function supersedesInvalidation(externalId, eventTime, runId) {
              const match = /^sfl-codex-review:(?:pull-context|base-advance):at:(\d+):(\d+)/.exec(externalId || "");
              if (!match) return false;
              const candidateTime = Number(match[1]);
              const candidateRunId = Number(match[2]);
              if (!Number.isSafeInteger(candidateTime) || !Number.isSafeInteger(candidateRunId)) return false;
              return candidateTime > eventTime ||
                (candidateTime === eventTime && candidateRunId > runId);
            }
            // END TESTABLE INVALIDATION ORDER

            const {owner, repo} = context.repo;
            const configuredBaseBranch = process.env.SFL_REVIEW_BASE_BRANCH || "";
            let baseRef = context.ref.replace(/^refs\/heads\//, "");
            let renamedBase = false;
            if (context.payload.deleted) {
              const repository = await github.rest.repos.get({owner, repo});
              const defaultBranch = repository.data.default_branch || "";
              if (!defaultBranch) throw new Error("Could not determine the repository default branch after base deletion");
              baseRef = defaultBranch;
              renamedBase = defaultBranch !== configuredBaseBranch;
            }
            const workflowRun = await github.rest.actions.getWorkflowRun({
              owner, repo, run_id: context.runId,
            });
            const baseAdvanceTime = Date.parse(workflowRun.data.created_at || "");
            if (!Number.isFinite(baseAdvanceTime)) {
              throw new Error("Could not determine the base-advance event time");
            }
            const openPulls = await github.paginate(github.rest.pulls.list, {
              owner, repo, state: "open", base: baseRef, per_page: 100,
            });
            const invalidatePull = async pull => {
              if (pull.base.ref !== baseRef) return;
              const invalidationId = `sfl-codex-review:base-advance:at:${baseAdvanceTime}:${context.runId}:${pull.number}`;
              const reviewerChecks = await github.paginate(
                github.rest.checks.listForRef,
                {
                  owner,
                  repo,
                  ref: pull.head.sha,
                  check_name: "SFL Reviewer Gate Runner",
                  filter: "all",
                  per_page: 100,
                },
                response => response.data,
              );
              const existingInvalidation = reviewerChecks.some(
                check => check.app && check.app.id === 15368 && check.external_id === invalidationId,
              );
              if (existingInvalidation) {
                core.info(`Pull request #${pull.number} already has this exact invalidation; skipping rerun`);
                return;
              }
              const supersedingContext = reviewerChecks.find(
                check => check.app && check.app.id === 15368 &&
                  supersedesInvalidation(check.external_id, baseAdvanceTime, context.runId),
              );
              if (supersedingContext) {
                core.info(`Pull request #${pull.number} has a newer invalidation context; skipping stale invalidation`);
                return;
              }
              const newerSuccess = reviewerChecks.some(
                check => check.app && check.app.id === 15368 &&
                  check.conclusion === "success" &&
                  check.external_id && check.external_id.startsWith(
                    `sfl-codex-review:pull:${pull.number}:base:${pull.base.sha.toLowerCase()}:`,
                  ) &&
                  check.external_id.includes(`:context:${encodeURIComponent(invalidationId)}:`),
              );
              if (newerSuccess) {
                core.info(`Pull request #${pull.number} already has a successful Codex gate completed after this base advance`);
                return;
              }
              const reason = renamedBase
                ? `Repository default branch changed from deployed SFL review base ${configuredBaseBranch} to ${baseRef}; redeploy SFL before requesting a new Codex review.`
                : `Pull request base ${baseRef} advanced to ${pull.base.sha}; update this PR branch from ${baseRef} to a new head, then request a Codex review with gh sfl review --repo ${owner}/${repo} --pr ${pull.number}.`;
              const finalChecks = await github.paginate(
                github.rest.checks.listForRef,
                {
                  owner,
                  repo,
                  ref: pull.head.sha,
                  check_name: "SFL Reviewer Gate Runner",
                  filter: "all",
                  per_page: 100,
                },
                response => response.data,
              );
              const finalContextExists = finalChecks.some(
                check => check.app && check.app.id === 15368 &&
                  (check.external_id === invalidationId ||
                   supersedesInvalidation(check.external_id, baseAdvanceTime, context.runId)),
              );
              const finalSuccess = finalChecks.some(
                check => check.app && check.app.id === 15368 &&
                  check.conclusion === "success" &&
                  check.external_id && check.external_id.startsWith(
                    `sfl-codex-review:pull:${pull.number}:base:${pull.base.sha.toLowerCase()}:`,
                  ) &&
                  check.external_id.includes(`:context:${encodeURIComponent(invalidationId)}:`),
              );
              if (finalContextExists || finalSuccess) {
                core.info(`Pull request #${pull.number} received a newer context or successful Codex gate while invalidation was running`);
                return;
              }
              await github.rest.checks.create({
                owner,
                repo,
                name: "SFL Reviewer Gate Runner",
                head_sha: pull.head.sha,
                status: "completed",
                conclusion: "failure",
                completed_at: new Date().toISOString(),
                details_url: pull.html_url,
                external_id: invalidationId,
                output: {title: "SFL Codex review invalidated", summary: reason},
              });
              await github.rest.repos.createCommitStatus({
                owner,
                repo,
                sha: pull.head.sha,
                state: "failure",
                context: "SFL Reviewer Gate Runner",
                target_url: pull.html_url,
                description: "The reviewed base branch advanced after review",
              });
            };
            const failures = [];
            const batchSize = 10;
            for (let offset = 0; offset < openPulls.length; offset += batchSize) {
              const batch = openPulls.slice(offset, offset + batchSize);
              const results = await Promise.allSettled(batch.map(invalidatePull));
              results.forEach((result, index) => {
                if (result.status === "rejected") {
                  failures.push(`PR #${batch[index].number}: ${result.reason}`);
                }
              });
            }
            if (failures.length > 0) {
              throw new Error(`Base-advance invalidation failed after attempting every pull request:\n${failures.join("\n")}`);
            }
